hooks.command:
python3 -c 'import json, os, re, subprocess, sys
d = os.environ.get("CLAUDE_PROJECT_DIR", ".")
p = os.path.join(d, ".claude/hooks/require-codex-review.py")
src = ""
if os.path.isfile(p):
    src = open(p, encoding="utf-8").read()
else:
    for ref in ("origin/dev", "origin/main"):
        r = subprocess.run(["git", "-C", d, "show", ref + ":.claude/hooks/require-codex-review.py"], capture_output=True, text=True)
        if r.returncode == 0:
            src = r.stdout
            break
if src:
    exec(compile(src, p, "exec"), {"__name__": "__main__"})
c = (json.load(sys.stdin).get("tool_input") or {}).get("command") or ""
if re.search(r"\bgh\b.*\bpr\b", c, re.S):
    print("require-codex-review 훅을 찾지 못해 PR 관련 명령을 차단합니다. 훅이 있는 브랜치에서 실행하세요.", file=sys.stderr)
    sys.exit(2)' || { rc=$?; [ $rc -eq 2 ] || echo "require-codex-review 훅 실행 실패(코드 $rc). python3 확인 필요. 안전을 위해 차단합니다." >&2; exit 2; }
